INSERT INTO `hotfixes`.`spell` (`ID`, `NameSubtext`, `Description`, `AuraDescription`, `VerifiedBuild`) VALUES
(1408001, '', 'Hurl a sphere of Azerite fire that burns the target.', 'Hurl a sphere of Azerite fire that burns the target.', 69933),
(1408002, '', 'Fire a beam of Azerite that sears the target.', 'Fire a beam of Azerite that sears the target.', 69933),
(1408003, '', 'Drive a spike of Azerite into the target.', 'Drive a spike of Azerite into the target.', 69933),
(1408004, '', 'Hurl a bolt of ruinous shadow at the target.', 'Hurl a bolt of ruinous shadow at the target.', 69933),
(1408005, '', 'Burn the target with reaping flames, stronger against the weakened.', 'Burn the target with reaping flames, stronger against the weakened.', 69933),
(1408006, '', 'Draw the blood of your enemy to strengthen yourself.', 'Draw the blood of your enemy to strengthen yourself.', 69933),
(1408007, '', 'Unleash a rift of raw power on the target.', 'Unleash a rift of raw power on the target.', 69933),
(1408008, '', 'Rip into the target, leaving a bleeding wound.', 'Rip into the target, leaving a bleeding wound.', 69933),
(1408009, '', 'Call your allies'' spirits to strike the target.', 'Call your allies'' spirits to strike the target.', 69933),
(1408010, '', 'A thunderous blast shakes the target.', 'A thunderous blast shakes the target.', 69933),
(1408011, '', 'A preserving spirit mends you over time.', 'A preserving spirit mends you over time.', 69933),
(1408012, '', 'A ward of venom wraps you and absorbs damage.', 'A ward of venom wraps you and absorbs damage.', 69933),
(1408013, '', 'A coil of souls mends the wounded.', 'A coil of souls mends the wounded.', 69933);
